package config

import "testing"

// TestConfigsMd_NonEmpty verifies the embedded configuration documentation is
// non-empty (the configs.md content is generated by cmd/configdocs and embedded
// at compile time).
func TestConfigsMd_NonEmpty(t *testing.T) {
	if ConfigsMd() == "" {
		t.Error("ConfigsMd() must return the embedded configs.md content, got empty string")
	}
}
